import sys

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    n = int(lines[0].strip())
    arr = []
    for i in range(1, n + 1):
        arr.append(int(lines[i].strip()))
    print("Array contents: [" + ", ".join(map(str, arr)) + "]")

if __name__ == "__main__":
    main()
